import json
import sys

def positions(entries):
    if type(entries) is not list or len(entries) > 4096:
        raise ValueError("entries")
    result = []
    for item in entries:
        if type(item) is not list or len(item) != 2:
            raise ValueError("pair")
        cursor, outcome = item
        if type(cursor) is not dict or cursor.keys() != {"label", "pos"}:
            raise ValueError("cursor")
        if type(cursor["label"]) is not str or outcome not in ("waiting", "finish"):
            raise ValueError("label or outcome")
        pos = cursor["pos"]
        if type(pos) is not int or not -(1 << 63) <= pos < (1 << 63):
            raise ValueError("pos")
        result.append(pos)
    return result

print(json.dumps(positions(**json.loads(sys.argv[1])), separators=(",", ":")))

